// Defer genuine SHA-256 work to exercise the actual async persistence boundary.
function delayDeviceDraftDigests(){
 const original=crypto.subtle.digest.bind(crypto.subtle),started=deviceDeferred(),held=deviceDeferred();let hold=true,calls=0,completed=0;
 const spy=vi.spyOn(crypto.subtle,'digest').mockImplementation(async(algorithm,data)=>{
  const captured=hold;calls++;if(captured)started.resolve();const result=await original(algorithm,data);if(captured)await held.promise;completed++;return result;
 });
 return {started:started.promise,allowNew(){hold=false;},release(){hold=false;held.resolve();},get calls(){return calls;},get completed(){return completed;},close(){hold=false;held.resolve();spy.mockRestore();}};
}
