import * as roomReview from '../../../src/lib/pos/room-charge-review-command';
function roomReviewRow(stage:'pos'|'pms'='pos'):roomReview.RoomChargeReviewRow{return {id:'review-request',company_id:'company',branch_id:'branch',sale_id:'linked-sale',property_id:'property',sale_version:4,property_version:7,restock_line_ids_json:'["native-stock-line"]',number:'POS-ORIGINAL',state:stage==='pos'?'requested':'pos_approved',version:stage==='pos'?1:2,reason:'Original requested reversal',amount_minor:10700,requested_by:'original-requester',pos_approved_by:stage==='pms'?'earlier-pos-reviewer':null,created_by:'original-sale-creator',charged_by:'original-room-charger',updated_at:1,source_current:true,stage,canAct:true,canApprove:true,reasonDisabled:null};}
function roomReviewBrowser(stage:'pos'|'pms'='pos'){
 const browser=deviceBrowser(),store={getItem:(key:string)=>browser.session.get(key)??null,setItem:(key:string,value:string)=>{browser.session.set(key,value);},removeItem:(key:string)=>{browser.session.delete(key);}},source:roomReview.RoomChargeReviewSource={base:'/holdings/acme',propertyId:stage==='pms'?'property':undefined,owner:{userId:'worker',companyId:'company',...(stage==='pms'?{property:{id:'property',companyId:'company',branchId:'branch',version:7}}:{})},rows:[roomReviewRow(stage)]};let live:roomReview.RoomChargeReviewSource|null=source;
 const commands=roomReview.createRoomChargeReviewCommands(()=>live,workFetch,()=>store),saved:Event[]=[];browser.browser.addEventListener('erpx:record-command-saved',event=>saved.push(event));return {...browser,store,source,commands,saved,key:roomReview.roomChargeReviewStorageKey(source),decision:roomReview.roomChargeDecisionSource(source.rows[0]),bind:(value:roomReview.RoomChargeReviewSource|null)=>{live=value;},read:()=>live};
}
function roomReviewNative(stage:'pos'|'pms'='pos',reject=false){
 const receipts=new Map<string,{body:string;result:Record<string,unknown>}>(),posts:{url:string;init:RequestInit}[]=[];let effects=0;
 const request=async(url:RequestInfo|URL,init?:RequestInit)=>{if(init?.method!=='POST')return Response.json({data:[]});posts.push({url:String(url),init});const key=new Headers(init.headers).get('Idempotency-Key')!,body=String(init.body),prior=receipts.get(key);if(prior){expect(body).toBe(prior.body);const r=repository<PosRepository<PosEffect>>({assertProductionModuleEnabled:async()=>{},readAssignments1:async()=>({id:'assignment'}),batch:async()=>{},workContextGuards:()=>[],iamMutationGuards:()=>[],writeContext1:async()=>({results:[]}),readPosReceipts1:async()=>({request_hash:'request-hash',result_json:JSON.stringify(prior.result)}),writeCommandAssertions1:async()=>({results:[]})});r.transaction=async run=>run(r);return Response.json({data:await commands().posCommand(r,actor,`room_charge_reversal.${reject?'reject':'approve'}_${stage}`,JSON.parse(body),key)});}effects++;const result:Record<string,unknown>=reject?{id:'review-request',saleId:'linked-sale',state:'rejected',version:stage==='pos'?2:3}:stage==='pos'?{id:'review-request',saleId:'linked-sale',state:'pos_approved',version:2}:{id:'review-request',saleId:'linked-sale',state:'room_charge_reversed',reversalEntryId:'native-reversal-entry',restoredCostMinor:3000,wastedCostMinor:12000};receipts.set(key,{body,result});return Response.json({data:result});};return{request,posts,effects:()=>effects};
}
